import React, { useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { STORAGE_KEY, stages, team, modules, lessons, newState, loadState, money, evaluateAnswer, searchKnowledge } from './model.mjs';
import './style.css';
import './crm.css';
import { Icon, Avatar, Badge, Button, AIFlag, Modal, PageTitle, Empty, Sparkline } from './ui.jsx';
import { roleViews, canVisit, scopeData, applyScopedUpdate } from './access.mjs';
import { TeamDetail, AccessInfo } from './workspaces.jsx';
import { DayHome, SalesReview, Training, KnowledgeList } from './crm.jsx';
import { dateFields, createDeadline, deadlineLabel, isOverdue, needsReply } from './crm-model.mjs';

const nav = [
  { id: 'overview', name: 'Мой день', icon: 'calendar' },
  { id: 'clients', name: 'Клиенты и сделки', icon: 'users' },
  { id: 'inbox', name: 'Переписки', icon: 'chat' },
  { id: 'analytics', name: 'Разбор продаж', icon: 'chart' },
  { id: 'academy', name: 'Обучение', icon: 'book' },
];
function readRole() {
  const query = new URLSearchParams(location.search).get('role');
  if (query === 'employee' || query === 'manager') return query;
  try { return localStorage.getItem('royal-reach-role') === 'employee' ? 'employee' : 'manager'; } catch { return 'manager'; }
}
function App() {
  const [state,setState]=useState(()=>loadState(localStorage));
  const [role,setRole]=useState(readRole);
  const [requestedPage,setRequestedPage]=useState(()=>location.hash.slice(1)||'overview');
  const page=requestedPage==='team'&&role==='manager'?'academy':canVisit(role,requestedPage)?requestedPage:'overview';
  const [modal,rawSetModal]=useState(null);
  const [toast,setToast]=useState('');
  const [selectedClient,setSelectedClient]=useState('alex');
  const [storageWarning,setStorageWarning]=useState(false);
  const [mobileNav,setMobileNav]=useState(false);
  const [quickQuery,setQuickQuery]=useState('');
  const [searchOpen,setSearchOpen]=useState(false);
  const [clientFilter,setClientFilter]=useState('all');
  const [waitingOnly,setWaitingOnly]=useState(false);
  const [,refreshClock]=useState(0);
  useEffect(()=>{const timer=setInterval(()=>refreshClock(n=>n+1),30000);return()=>clearInterval(timer);},[]);
  const data=scopeData(state,role);
  const currentNav=page==='knowledge'?'academy':page;
  const searchResults=quickQuery.trim().length>0?data.clients.filter(c=>(c.name+' '+c.company).toLowerCase().includes(quickQuery.trim().toLowerCase())).slice(0,6):[];
  const awaiting=data.clients.filter(needsReply).length;
  useEffect(()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{setStorageWarning(true);}},[state]);
  useEffect(()=>{const listener=()=>setRequestedPage(location.hash.slice(1)||'overview');window.addEventListener('hashchange',listener);return()=>window.removeEventListener('hashchange',listener);},[]);
  useEffect(()=>{if(page!==requestedPage)location.hash=page;},[page,requestedPage]);
  useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4000);return()=>clearTimeout(t);},[toast]);
  useEffect(()=>{document.title=`${nav.find(n=>n.id===currentNav)?.name||'Royal Reach'} · ${role==='manager'?'Руководитель':'Сотрудник'} · Royal Reach`;},[page,role]);
  useEffect(()=>{const key=e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setModal({type:'search'});}if(e.key==='Escape'){setMobileNav(false);setSearchOpen(false);}};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key);},[role]);
  function notify(text){setToast(text);}
  function go(id,options={}){
    if(!canVisit(role,id)){notify('Этот раздел доступен руководителю');return;}
    if(id==='clients')setClientFilter(String(options.stage??'all'));
    if(id==='inbox'){const first=options.waiting?data.clients.find(needsReply):null;setWaitingOnly(Boolean(first));if(first)setSelectedClient(first.id);}
    location.hash=id;setRequestedPage(id);rawSetModal(null);setMobileNav(false);setSearchOpen(false);setQuickQuery('');window.scrollTo({top:0,behavior:'instant'});
  }
  function openChat(id){if(!data.clients.some(c=>c.id===id))return;setSelectedClient(id);go('inbox');}
  function update(fn){setState(prev=>applyScopedUpdate(prev,role,fn));}
  function setModal(value){
    if(!value)return rawSetModal(null);
    if(role==='employee'&&(['newKnowledge','integration','settings','reset','teamDetail'].includes(value.type)||(['person','report'].includes(value.type)&&value.person&&value.person.id!==1))){notify('Действие доступно руководителю');return;}
    if(value.clientId&&!data.clients.some(c=>c.id===value.clientId))return;
    rawSetModal(value);setSearchOpen(false);setQuickQuery('');
  }
  function changeRole(next){
    if(next===role)return;setRole(next);rawSetModal(null);setRequestedPage('overview');setSelectedClient('alex');setMobileNav(false);setQuickQuery('');setSearchOpen(false);
    const url=new URL(location.href);url.searchParams.set('role',next);url.hash='overview';history.replaceState(null,'',url);try{localStorage.setItem('royal-reach-role',next);}catch{}
    window.scrollTo({top:0,behavior:'instant'});
  }
  function exportData(){if(role!=='manager')return;const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='royal-reach-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  const ctx={data,role,update,go,openChat,setModal,notify,selectedClient,setSelectedClient};
  const profile=role==='manager'?{name:'Руководитель',initials:'РК',color:'sage'}:team[0];
  return <div className={`crm-app role-${role}`}>
    {mobileNav&&<button className="crm-nav-scrim" aria-label="Закрыть меню" onClick={()=>setMobileNav(false)}/>}
    <aside className={`crm-sidebar ${mobileNav?'open':''}`}><button className="crm-brand" aria-label="Royal Reach — на главную" onClick={()=>go('overview')}>ROYAL REACH<small>CRM</small></button><nav aria-label="Основная навигация">{nav.map(n=><button key={n.id} onClick={()=>go(n.id)} className={currentNav===n.id?'active':''} aria-current={currentNav===n.id?'page':undefined}><Icon name={n.icon} size={19}/><span>{n.name}</span>{n.id==='inbox'&&awaiting>0&&<b>{awaiting}</b>}</button>)}</nav><div className="crm-sidebar-bottom"><button className="crm-help" onClick={()=>setModal({type:'about'})}><Icon name="help" size={18}/>Помощь</button><div className="crm-profile"><Avatar person={profile}/><span><strong>{profile.name}</strong><small>{role==='manager'?'Вся команда':'Сотрудник'}</small></span></div></div></aside>
    <div className="crm-workspace"><header className="crm-topbar"><button className="icon-btn crm-menu-button" aria-label="Открыть меню" onClick={()=>setMobileNav(!mobileNav)}><Icon name="menu"/></button><div className="crm-quick-search" onBlur={e=>{if(!e.currentTarget.contains(e.relatedTarget))setSearchOpen(false);}}><form onSubmit={e=>{e.preventDefault();if(searchResults.length===1)setModal({type:'client',clientId:searchResults[0].id});else if(quickQuery.trim())setModal({type:'search',query:quickQuery});}}><Icon name="search" size={17}/><input aria-label="Поиск клиента или сделки" placeholder="Поиск клиента или сделки" value={quickQuery} onChange={e=>{setQuickQuery(e.target.value);setSearchOpen(true);}} onFocus={()=>setSearchOpen(true)}/>{quickQuery&&<button type="button" aria-label="Очистить поиск" onClick={()=>setQuickQuery('')}><Icon name="close" size={15}/></button>}</form>{searchOpen&&quickQuery.trim()&&<div className="crm-quick-results" role="group" aria-label="Результаты поиска">{searchResults.length?searchResults.map(c=><button key={c.id} onClick={()=>setModal({type:'client',clientId:c.id})}><Avatar person={c} size="small"/><span><strong>{c.company}</strong><small>{c.name}</small></span><Icon name="down" size={15}/></button>):<p>Клиент не найден</p>}</div>}</div><select className="crm-role-select" aria-label="Режим просмотра" value={role} onChange={e=>changeRole(e.target.value)}><option value="manager">Руководитель</option><option value="employee">Сотрудник</option></select><button className="icon-btn crm-notifications" aria-label="Открыть все задачи" title="Все задачи" onClick={()=>setModal({type:'tasks'})}><Icon name="bell" size={21}/>{data.tasks.some(t=>isOverdue(t))&&<i/>}</button><span className="crm-top-avatar"><Avatar person={profile} size="small"/></span></header>
    <main className={`crm-main view-${page}`} key={`${role}-${page}`}>
      {storageWarning&&<div role="status" className="storage-warning">Хранилище браузера недоступно. Изменения сохранятся до закрытия страницы.</div>}
      {page==='overview'&&<DayHome {...ctx}/>}
      {page==='inbox'&&<Inbox {...ctx} waitingOnly={waitingOnly}/>}
      {page==='clients'&&<Clients {...ctx} initialFilter={clientFilter}/>}
      {page==='analytics'&&<SalesReview {...ctx}/>}
      {page==='academy'&&<Training {...ctx}/>}
      {page==='knowledge'&&<><div className="crm-page-heading"><div><h1>База знаний</h1></div><Button variant="secondary" onClick={()=>go('academy')}>К обучению</Button></div><KnowledgeList {...ctx}/></>}
    </main><footer className="crm-footer">Макет · демонстрационные данные</footer></div>
    {toast&&<div role="status" className="toast"><span><Icon name="check" size={16}/></span>{toast}</div>}
    {modal&&<AppModal key={`${modal.type}-${modal.clientId||modal.person?.id||modal.moduleId||modal.taskId||''}`} modal={modal} onClose={()=>rawSetModal(null)} {...ctx} exportData={exportData}/>}
  </div>;
}

function Inbox({ data, update, selectedClient, setSelectedClient, setModal, notify, waitingOnly }) {
  const [query, setQuery] = useState(''); const [filter, setFilter] = useState(waitingOnly ? 'Требуют ответа' : 'Все'); const [draft, setDraft] = useState(''); const [tab, setTab] = useState('analysis'); const [busy, setBusy] = useState(false); const [analysed, setAnalysed] = useState(false); const messagesRef = useRef(null);
  const client = data.clients.find(c => c.id === selectedClient) || data.clients[0];
  useEffect(() => { setAnalysed(false); setDraft(''); update(d => ({ ...d, clients: d.clients.map(c => c.id === client.id && c.unread ? { ...c, unread: false } : c) })); }, [client.id]);
  useEffect(() => { if (messagesRef.current) messagesRef.current.scrollTop = messagesRef.current.scrollHeight; }, [client.id, client.messages.length]);
  const list = data.clients.filter(c => (filter === 'Все' || (filter === 'Требуют ответа' ? needsReply(c) : c.channel === filter)) && (c.name + c.company).toLowerCase().includes(query.toLowerCase()));
  function select(c) { setSelectedClient(c.id); update(d => ({ ...d, clients: d.clients.map(x => x.id === c.id ? { ...x, unread: false } : x) })); }
  function send(e) { e.preventDefault(); if (!draft.trim()) return; const text = draft.trim(); const time = new Intl.DateTimeFormat('ru-RU', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Moscow' }).format(new Date()); update(d => ({ ...d, clients: d.clients.map(c => c.id === client.id ? { ...c, unread: false, last: text, time, messages: [...c.messages, { from: 'me', text, time }] } : c) })); setDraft(''); notify('Ответ сохранён в демопереписке'); }
  function analyse() { setBusy(true); setTimeout(() => { setBusy(false); setAnalysed(true); }, 700); }
  return <><PageTitle eyebrow="ЕДИНОЕ ОКНО ОБЩЕНИЯ" title="Переписки" subtitle="Сообщения клиентов и следующий шаг по сделке."><Badge tone="gray" dot>MAX и Telegram · демоданные</Badge></PageTitle>
  <div className="inbox-layout panel"><aside className="conversation-list"><div className="conversation-list-head"><strong>Входящие <span>{data.clients.length}</span></strong><Icon name="chat" size={18} /></div><label className="input-search"><Icon name="search" size={16} /><input aria-label="Поиск по перепискам" placeholder="Имя или компания" value={query} onChange={e => setQuery(e.target.value)} /></label><div className="mini-tabs">{['Все', 'MAX', 'Telegram', 'Требуют ответа'].map(f => <button key={f} className={filter === f ? 'active' : ''} onClick={() => setFilter(f)}>{f}</button>)}</div><div className="conversations">{list.map(c => <button className={`conversation ${client.id === c.id ? 'selected' : ''}`} key={c.id} onClick={() => select(c)}><Avatar person={c} /><div><div><strong>{c.name.split(' ')[0]}</strong><time>{c.time}</time></div><span>{c.company}</span><p>{c.last}</p></div><span className={`channel-dot ${c.channel === 'MAX' ? 'max' : 'tg'}`}>{c.channel === 'MAX' ? 'M' : '↗'}</span>{c.unread && <i className="unread-dot" />}</button>)}{!list.length && <Empty />}</div><div className="list-foot"><Icon name="shield" size={13} />Вымышленные контакты для демонстрации</div></aside>
  <section className="chat-window"><header className="chat-head"><Avatar person={client} online /><div><h2>{client.name}</h2><span>{client.company} <i /> {client.channel}</span></div><button className="icon-btn" aria-label="Карточка клиента" onClick={() => setModal({ type: 'client', clientId: client.id })}><Icon name="external" size={18} /></button></header><div className="chat-stage"><span className="status-dot" />{stages[client.stage]}<span>{money(client.amount)}</span></div><button className="mobile-analysis" onClick={() => setModal({ type: 'review', clientId: client.id })}><Icon name="spark" size={14} />Разобрать диалог<span>Демо</span><Icon name="arrow" size={14} /></button><div className="chat-messages" ref={messagesRef}><div className="chat-date">28 октября · учебный диалог</div>{client.messages.map((m, i) => <div className={`message ${m.from}`} key={i}>{m.from === 'client' && <Avatar person={client} size="tiny" />}<div><p>{m.text}</p><time>{m.time}{m.from === 'me' && <Icon name="check" size={12} />}</time></div></div>)}<div className="chat-system"><Icon name="shield" size={13} />Сообщения сохраняются в макете и не отправляются клиентам</div></div><div className="composer-wrap"><button className="suggest-button" onClick={() => { setDraft(`${client.name.split(' ')[0]}, подскажите, какой результат вы хотите получить? Подберу два варианта под вашу задачу и подробно покажу состав каждого.`); notify('Учебный шаблон добавлен. Проверьте и отредактируйте ответ.'); }}><Icon name="spark" size={14} />Предложить ответ<span>Демо</span></button><form className="composer" onSubmit={send}><textarea aria-label="Сообщение клиенту" placeholder="Напишите ответ клиенту…" value={draft} onChange={e => setDraft(e.target.value)} onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) send(e); }} rows={2} maxLength={4000} /><div><span>Enter — сохранить · Shift + Enter — новая строка</span><button className="send-button" aria-label="Сохранить сообщение" disabled={!draft.trim()}><Icon name="send" size={18} /></button></div></form></div></section>
  <aside className="context-panel"><div className="context-tabs">{[['analysis', 'ИИ-разбор'], ['profile', 'Клиент']].map(([id, label]) => <button key={id} className={tab === id ? 'active' : ''} onClick={() => setTab(id)}>{label}</button>)}</div>{tab === 'analysis' ? <><div className="context-intro"><span className="ai-icon"><Icon name="spark" size={22} /></span><AIFlag>ИИ-помощник · демо</AIFlag><h3>Подсказка по диалогу</h3><p>Разберите диалог, чтобы увидеть задачу клиента и следующий шаг.</p></div><Button variant="secondary" icon={busy ? 'refresh' : 'spark'} className="full" disabled={busy} onClick={analyse}>{busy ? 'Разбираем учебный пример…' : analysed ? 'Повторить разбор' : 'Разобрать диалог'}</Button>{analysed ? <div className="analysis-result"><Badge tone="green">Учебный разбор готов</Badge><h4>Что видно из переписки</h4><p>Клиент обозначил задачу: «{client.need}». Важно связать предложение с ожидаемым результатом.</p><div className="quote-box">{client.messages.filter(m => m.from === 'client').at(-1)?.text}</div><h4>Что сделать дальше</h4><ul><li>Ответить на конкретный вопрос.</li><li>Уточнить критерий успешного результата.</li><li>Согласовать следующий шаг и срок.</li></ul><Button icon="book" onClick={() => setModal({ type: 'review', clientId: client.id })}>Создать учебный пример</Button><small>Готовый демосценарий. Настоящий ИИ не подключён.</small></div> : <><div className="context-card"><span className="eyebrow">ФОКУС РАЗГОВОРА</span><strong>{client.need}</strong><p>Источник: учебная карточка клиента</p></div><div className="context-tip"><Icon name="target" size={18} /><p>Хороший следующий шаг отвечает на вопрос: кто, что и к какому времени сделает?</p></div></>}</> : <div className="client-context"><Avatar person={client} size="large" /><h3>{client.name}</h3><p>{client.company}</p><dl><dt>Интерес</dt><dd>{client.interest}</dd><dt>Задача</dt><dd>{client.need}</dd><dt>Ответственный</dt><dd>{team.find(p => p.id === client.owner)?.name}</dd><dt>Источник</dt><dd>Демонстрационная карточка</dd></dl><Button variant="secondary" icon="plus" onClick={() => setModal({ type: 'task', clientId: client.id })}>Добавить задачу</Button></div>}</aside></div></>;
}

function Clients({data,role,setModal,openChat,initialFilter}) {
  const [query,setQuery]=useState('');const [filter,setFilter]=useState(initialFilter||'all');
  const list=data.clients.filter(c=>(filter==='all'||c.stage===Number(filter))&&(c.name+' '+c.company).toLowerCase().includes(query.toLowerCase()));
  return <><div className="crm-page-heading"><div><h1>Клиенты и сделки</h1><p>{role==='manager'?'Все клиенты команды.':'Ваши клиенты и текущие договорённости.'}</p></div><Button icon="plus" onClick={()=>setModal({type:'newClient'})}>Добавить клиента</Button></div><section className="crm-panel"><div className="table-toolbar"><label className="input-search"><Icon name="search" size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} aria-label="Поиск клиентов" placeholder="Найти клиента или компанию"/></label><select aria-label="Фильтр по этапу сделки" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Все этапы</option>{stages.map((s,i)=><option key={s} value={i}>{i===3?'Ожидаем оплату':s}</option>)}</select></div><div className="table-scroll"><table className="client-table"><thead><tr><th>Клиент / компания</th><th>Этап</th><th>Канал</th><th>Сумма</th>{role==='manager'&&<th>Ответственный</th>}<th/></tr></thead><tbody>{list.map(c=><tr key={c.id}><td><button className="table-person" onClick={()=>setModal({type:'client',clientId:c.id})}><Avatar person={c}/><span><strong>{c.name}</strong><small>{c.company}</small></span></button></td><td><Badge tone={c.stage===4?'green':c.stage===3?'purple':'gray'}>{c.stage===3?'Ожидаем оплату':stages[c.stage]}</Badge></td><td><span className="channel-label"><i className={c.channel==='MAX'?'max':'tg'}/>{c.channel}</span></td><td className="money-cell">{money(c.amount)}</td>{role==='manager'&&<td><span className="owner-name">{team.find(p=>p.id===c.owner)?.name}</span></td>}<td><button className="icon-btn" aria-label={`Открыть переписку: ${c.name}`} onClick={()=>openChat(c.id)}><Icon name="chat" size={18}/></button></td></tr>)}</tbody></table></div>{!list.length&&<Empty/>}<div className="table-foot">Найдено: {list.length}<span>Все контакты вымышлены</span></div></section></>;
}

function Integrations({ setModal }) {
  return <><PageTitle eyebrow="СВЯЗАННОЕ РАБОЧЕЕ ПРОСТРАНСТВО" title="Всё на своих местах" subtitle="Переписки, знания и ИИ — в одном понятном процессе."><Badge tone="sand">План подключения</Badge></PageTitle><div className="integration-notice"><Icon name="plug" size={20} /><div><strong>Здесь показана архитектура будущей системы</strong><p>Внешние сервисы не подключены. Все данные и действия в макете остаются в браузере.</p></div></div><div className="integration-grid">{[{ id: 'telegram', name: 'Telegram', symbol: '↗', color: 'telegram', desc: 'Переписки команды в едином окне', detail: '4 тестовых аккаунта', tag: 'Мессенджер' }, { id: 'max', name: 'MAX', symbol: 'M', color: 'max', desc: 'Контекст клиентских разговоров', detail: '4 тестовых аккаунта', tag: 'Мессенджер' }, { id: 'gpt', name: 'OpenAI GPT', symbol: '✺', color: 'gpt', desc: 'Разборы, практика и обратная связь', detail: 'Модели для разных задач', tag: 'Интеллект' }, { id: 'supabase', name: 'Supabase', symbol: 'ϟ', color: 'supabase', desc: 'История, знания и прогресс команды', detail: 'Общее хранилище и поиск', tag: 'Данные' }].map(p => <section className="integration-card panel" key={p.id}><div><span className={`service-logo ${p.color}`}>{p.symbol}</span><Badge tone="gray">{p.tag}</Badge></div><h2>{p.name}</h2><p>{p.desc}</p><div className="integration-detail"><Icon name={p.id === 'supabase' ? 'layers' : p.id === 'gpt' ? 'spark' : 'users'} size={16} />{p.detail}</div><footer><span><i />Не подключено</span><button className="text-link" onClick={() => setModal({ type: 'integration', id: p.id })}>Подробнее <Icon name="arrow" size={16} /></button></footer></section>)}</div><section className="panel architecture"><div className="panel-heading"><div><span className="eyebrow">КАК ДВИЖЕТСЯ ИНФОРМАЦИЯ</span><h2>Больше памяти. Меньше лишнего контекста.</h2></div><AIFlag>Будущая интеграция</AIFlag></div><div className="architecture-flow">{[{ icon: 'chat', title: 'Переписки', text: 'Сообщения и договорённости' }, { icon: 'layers', title: 'База знаний', text: 'История и утверждённые материалы' }, { icon: 'search', title: 'Отбор контекста', text: 'Только нужные фрагменты' }, { icon: 'spark', title: 'GPT', text: 'Ответ с указанием источников' }].map((s, i) => <React.Fragment key={s.title}><div className="architecture-step"><span><Icon name={s.icon} size={22} /></span><h3>{s.title}</h3><p>{s.text}</p></div>{i < 3 && <Icon name="arrow" className="flow-arrow" size={20} />}</React.Fragment>)}</div><p className="architecture-caption">В GPT передаётся выбранный контекст, а не вся история базы. Экономия токенов зависит от настройки поиска и проверяется на реальной нагрузке.</p></section></>;
}

function AppModal({ modal, onClose, data, update, setModal, notify, go, openChat, exportData, role }) {
  const c = data.clients.find(c => c.id === modal.clientId);
  if (modal.type === 'access') return <AccessInfo onClose={onClose} />;
  if (modal.type === 'teamDetail') return <TeamDetail person={modal.person} data={data} setModal={setModal} onClose={onClose} openChat={openChat} />;
  if (['review', 'client'].includes(modal.type) && !c) return null;
  if (modal.type === 'lesson') return <Lesson modal={modal} onClose={onClose} data={data} update={update} notify={notify} />;
  if (modal.type === 'review') return <Review role={role} client={c} onClose={onClose} data={data} update={update} notify={notify} go={go} />;
  if (modal.type === 'search') return <GlobalSearch initialQuery={modal.query} role={role} data={data} onClose={onClose} openChat={openChat} setModal={setModal} go={go} />;
  if (modal.type === 'ask') return <AskKnowledge data={data} onClose={onClose} setModal={setModal} />;
  if (modal.type === 'newClient') return <NewClient role={role} onClose={onClose} update={update} notify={notify} />;
  if (modal.type === 'newKnowledge') return <NewKnowledge onClose={onClose} update={update} notify={notify} />;
  if (modal.type === 'task') return <NewTask data={data} client={c} onClose={onClose} update={update} notify={notify} />;
  if (modal.type === 'taskDetail') {
    const task = data.tasks.find(t => t.id === modal.taskId);
    if (!task) return null;
    const client = data.clients.find(c => c.id === task.clientId);
    return <Modal title="Задача" onClose={onClose}><h3 className="task-detail-title">{task.title}</h3><dl className="detail-list"><dt>Клиент</dt><dd>{client?.company || 'Без клиента'}</dd><dt>Срок</dt><dd className={isOverdue(task) ? 'overdue' : ''}>{deadlineLabel(task,true)}{isOverdue(task) ? ' · Просрочено' : ''}</dd><dt>Часовой пояс</dt><dd>Москва (UTC+3)</dd>{task.deadlineMode==='within24h'&&<><dt>Отсчёт</dt><dd>24 часа с момента создания задачи. Открытие карточки не продлевает срок.</dd></>}</dl><div className="modal-actions">{client && <Button variant="secondary" onClick={() => { onClose(); openChat(client.id); }}>Открыть переписку</Button>}<Button icon="check" onClick={() => { update(d => ({ ...d, tasks: d.tasks.map(t => t.id === task.id ? { ...t, done: !t.done } : t) })); onClose(); notify(task.done ? 'Задача возвращена в работу' : 'Задача выполнена'); }}>{task.done ? 'Вернуть в работу' : 'Выполнить задачу'}</Button></div></Modal>;
  }
  if (modal.type === 'client') return <Modal title={c.name} eyebrow="КАРТОЧКА КЛИЕНТА" onClose={onClose}><div className="modal-person"><Avatar person={c} size="large" /><div><h3>{c.company}</h3><span>{c.channel} · {money(c.amount)}</span></div></div><dl className="detail-list"><dt>Задача клиента</dt><dd>{c.need}</dd><dt>Интерес</dt><dd>{c.interest}</dd><dt>Ответственный</dt><dd>{team.find(p => p.id === c.owner)?.name}</dd></dl><label className="form-label">Этап сделки<select value={c.stage} onChange={e => update(d => ({ ...d, clients: d.clients.map(x => x.id === c.id ? { ...x, stage: Number(e.target.value) } : x) }))}>{stages.map((s, i) => <option value={i} key={s}>{s}</option>)}</select></label><div className="modal-actions"><Button variant="secondary" icon="plus" onClick={() => setModal({ type: 'task', clientId: c.id })}>Задача</Button><Button icon="chat" onClick={() => { onClose(); openChat(c.id); }}>Открыть переписку</Button></div><p className="small-note">Учебный контакт. Изменения сохраняются только в этом браузере.</p></Modal>;
  if (modal.type === 'article') return <Modal title={modal.article.title} eyebrow={modal.article.category.toUpperCase()} onClose={onClose}><div className="article-meta"><Badge tone="green"><Icon name="shield" size={12} />Утверждено</Badge><span>{modal.article.updated}</span></div><div className="article-body">{modal.article.body.split('\n').map((p, i) => <p key={i}>{p}</p>)}</div><div className="source-box"><Icon name="file" size={19} /><div><small>Источник</small><strong>{modal.article.source}</strong></div></div><div className="modal-actions"><Button icon="book" onClick={() => setModal({ type: 'lesson', moduleId: 1, daily: true })}>Закрепить на практике</Button></div></Modal>;
  if (modal.type === 'tasks') return <Modal title="Все задачи" eyebrow="ОБЕЩАНИЯ ПОД КОНТРОЛЕМ" onClose={onClose}><div className="modal-task-list">{data.tasks.map(t => <div key={t.id} className={`task-row ${t.done ? 'done' : ''}`}><button className={`task-check ${t.done ? 'checked' : ''}`} aria-label={`${t.done ? 'Вернуть' : 'Выполнить'}: ${t.title}`} onClick={() => update(d => ({ ...d, tasks: d.tasks.map(x => x.id === t.id ? { ...x, done: !x.done } : x) }))}><Icon name="check" size={13} /></button><button className="task-summary" onClick={()=>setModal({type:'taskDetail',taskId:t.id})}><strong>{t.title}</strong><span>{data.clients.find(c => c.id === t.clientId)?.name || 'Команда'}</span></button><span className={`task-time ${isOverdue(t)?'overdue':''}`}>{deadlineLabel(t)}{isOverdue(t)&&<small>Просрочено</small>}</span></div>)}</div><div className="modal-actions"><Button icon="plus" onClick={() => setModal({ type: 'task' })}>Добавить задачу</Button></div></Modal>;
  if (modal.type === 'person' || modal.type === 'report') { const p = modal.person || team[0]; return <Modal title={p.name} eyebrow="КАРТА НАВЫКОВ · УЧЕБНЫЙ ПРИМЕР" onClose={onClose}><div className="modal-person"><Avatar person={p} size="large" /><div><h3>{p.score} / 100</h3><span>Качество диалогов · {p.role}</span></div></div>{['Понимание задачи', 'Уточняющие вопросы', 'Работа с возражениями', 'Следующий шаг'].map((s, i) => <div className="competency" key={s}><div><span>{s}</span><strong>{p.skills[i]}</strong></div><div className="progress-track"><span style={{ width: `${p.skills[i]}%` }} /></div></div>)}<div className="report-observation"><h3>Сильная сторона</h3><p>Сохраняет спокойный тон и помогает клиенту сформулировать задачу.</p><h3>Следующий навык</h3><p>Уточнять причину возражения до того, как предлагать скидку. Практика: два диалога с сомневающимся клиентом.</p></div><p className="small-note">Это демонстрационная сводка навыков. В рабочей версии каждый вывод должен иметь цитаты и проверку наставника.</p><div className="modal-actions"><Button icon="book" onClick={() => { onClose(); go('academy'); }}>{role === 'manager' ? 'Обучение команды' : 'Открыть обучение'}</Button></div></Modal>; }
  if (modal.type === 'integration') { const details = { telegram: ['Telegram', 'Четыре тестовых аккаунта для проверки входящих сообщений, ответов, распределения диалогов и восстановления соединения.', 'Способ доступа к перепискам выбирается при интеграции. Наличие аккаунта само по себе не подключает его к CRM.'], max: ['MAX', 'Четыре тестовых аккаунта для проверки сценариев общения и импорта доступной истории.', 'Возможность доступа к личным перепискам зависит от разрешённых интерфейсов MAX. Перед разработкой интеграции нужно проверить конкретный способ подключения.'], gpt: ['OpenAI GPT', 'Массовые задачи направляются в экономичную модель. Сложные разборы и спорные ответы — в более сильную. В каждом случае передаётся выбранный контекст.', 'API-ключ хранится на сервере. Этот публичный макет не принимает ключи и не делает запросы к OpenAI.'], supabase: ['Supabase', 'Общая база хранит клиентов, сообщения, права доступа, учебные материалы и прогресс. Поиск выбирает относящиеся к вопросу фрагменты.', 'В рабочей версии потребуются серверная проверка доступа и резервное копирование. Сейчас данные хранятся в localStorage этого браузера.'] }[modal.id]; return <Modal title={details[0]} eyebrow="ПЛАН ИНТЕГРАЦИИ" onClose={onClose}><Badge tone="sand">Не подключено</Badge><div className="article-body"><p>{details[1]}</p><p>{details[2]}</p></div><div className="source-box"><Icon name="plug" size={22} /><p>Этот экран объясняет будущую функцию. Подключение сервиса в макете не выполняется.</p></div></Modal>; }
  if (modal.type === 'settings') return <Modal title="Настройки демонстрации" eyebrow="ВАШЕ РАБОЧЕЕ ПРОСТРАНСТВО" onClose={onClose}><div className="settings-option"><div><strong>Экспорт демоданных</strong><p>Скачать клиентов, задачи и прогресс в JSON.</p></div><Button variant="secondary" icon="download" onClick={exportData}>Скачать</Button></div><div className="settings-option"><div><strong>Начать демонстрацию заново</strong><p>Вернуть учебные данные и исходный прогресс.</p></div><Button variant="secondary" icon="refresh" onClick={() => setModal({ type: 'reset' })}>Сбросить</Button></div><p className="small-note">Не добавляйте в публичный макет реальные персональные данные. Серверное хранение и авторизация не подключены.</p></Modal>;
  if (modal.type === 'reset') return <Modal title="Начать заново?" eyebrow="СБРОС ДЕМО" onClose={onClose}><p className="modal-copy">Созданные в этом браузере демоклиенты, сообщения, задания и учебный прогресс будут заменены исходным примером. Перед сбросом можно скачать экспорт.</p><div className="modal-actions"><Button variant="secondary" onClick={exportData}>Скачать экспорт</Button><Button onClick={() => { update(() => newState()); onClose(); notify('Демонстрация начата заново'); go('overview'); }}>Сбросить демоданные</Button></div></Modal>;
  return <Modal title="О макете" onClose={onClose}><div className="article-body"><p>Руководитель видит работу всей команды. Сотрудник — свои переписки, клиентов, задачи и обучение.</p><p>Все данные вымышлены. Сообщения сохраняются в этом браузере и никому не отправляются. ИИ-разборы показывают подготовленные учебные примеры.</p><p>Авторизация, GPT API и мессенджеры в макете не подключены. Режим просмотра переключается вверху страницы.</p></div><div className="modal-actions"><Button onClick={onClose}>Понятно</Button></div></Modal>;
}

function Lesson({ modal, onClose, data, update, notify }) {
  const [step, setStep] = useState(0); const [choice, setChoice] = useState(null); const [answer, setAnswer] = useState(''); const [evaluation, setEvaluation] = useState(null); const [finished, setFinished] = useState(false); const [awarded, setAwarded] = useState(0);
  const id = modal.moduleId; const module = modules[id]; const lesson = lessons[id];
  const titles = [lesson.title, 'Выберите следующий шаг', 'Попробуйте своими словами', 'Навык стал чуть сильнее'];
  function finish() { if (finished) return; const reward = modal.daily ? (data.dailyDone ? 0 : 40) : (data.completed.includes(id) ? 0 : 60); setAwarded(reward); setFinished(true); update(d => ({ ...d, completed: modal.daily ? d.completed : [...new Set([...d.completed, id])], xp: d.xp + reward, dailyDone: modal.daily ? true : d.dailyDone, streak: modal.daily && !d.dailyDone ? d.streak + 1 : d.streak, activity: [...d.activity, { type: 'lesson', moduleId: id, at: new Date().toISOString() }] })); setStep(3); }
  return <Modal title={titles[step]} eyebrow={`${modal.daily ? 'ЕЖЕДНЕВНАЯ ПРАКТИКА' : `БЛОК ${id + 1} · ${module.title.toUpperCase()}`} · ${Math.min(step + 1, 3)} / 3`} onClose={onClose} wide><div className="lesson-progress">{[0, 1, 2].map(n => <span key={n} className={step >= n ? 'active' : ''} />)}</div>{step === 0 && <div className="lesson-content"><div className="lesson-art"><Icon name="chat" size={45} /><span>{lesson.motto}</span></div><p className="lesson-lead">{lesson.lead}</p><div className="lesson-comparison"><div><span>Слишком рано</span><p>{lesson.bad}</p></div><div><span><Icon name="check" size={14} />Лучше начать так</span><p>{lesson.good}</p></div></div><div className="source-inline"><Icon name="file" size={15} />Учебный стандарт: «{lesson.source}»</div><div className="modal-actions"><Button onClick={() => setStep(1)}>Понятно, дальше <Icon name="arrow" size={16} /></Button></div></div>}{step === 1 && <div className="lesson-content"><div className="quiz-context"><Avatar person={data.clients[0]} /><div><strong>Алексей · учебный клиент</strong><p>«{lesson.quote}»</p></div></div><h3 className="quiz-title">Какой ответ помогает продолжить разговор?</h3><div className="quiz-options">{lesson.options.map((a, i) => <button key={a} className={`${choice === i ? 'selected' : ''} ${choice === i && i === 1 ? 'correct' : choice === i ? 'incorrect' : ''}`} onClick={() => setChoice(i)}><span>{String.fromCharCode(65 + i)}</span>{a}{choice === i && i === 1 && <Icon name="check" size={18} />}</button>)}</div>{choice !== null && <div role="status" className={`quiz-feedback ${choice === 1 ? 'success' : 'retry'}`}><strong>{choice === 1 ? 'Да, это помогает клиенту.' : 'Попробуйте ещё раз.'}</strong><p>{choice === 1 ? lesson.why : 'Ответ должен раскрыть состав предложения и помочь понять задачу. Давление и скидка пока не решают вопрос.'}</p></div>}<div className="modal-actions"><Button variant="ghost" onClick={() => setStep(0)}>Назад</Button><Button disabled={choice !== 1} onClick={() => setStep(2)}>К практике <Icon name="arrow" size={16} /></Button></div></div>}{step === 2 && <div className="lesson-content"><div className="roleplay-label"><Badge tone="green">Ролевой диалог</Badge><span>Учебный сценарий · локальная проверка</span></div><div className="roleplay-client"><Avatar person={data.clients[0]} /><div><strong>Алексей</strong><p>{lesson.practice}</p></div></div><label className="form-label">Ваш ответ<textarea rows={5} placeholder="Ответьте клиенту своими словами. Уточните задачу, задайте вопрос и предложите следующий шаг…" value={answer} onChange={e => { setAnswer(e.target.value); setEvaluation(null); }} maxLength={3000} /></label><div className="practice-meta"><span>Не меньше 30 символов</span><span>{answer.length} / 3 000</span></div>{evaluation && <div role="status" className="practice-evaluation"><h3>{evaluation.score === 3 && evaluation.valid ? 'Есть всё, чтобы продолжить диалог' : 'Хорошее начало. Давайте усилим ответ.'}</h3>{evaluation.checks.map(c => <div key={c.label} className={c.pass ? 'pass' : 'miss'}><Icon name={c.pass ? 'check' : 'plus'} size={16} />{c.label}<small>{c.pass ? 'Есть' : 'Добавьте'}</small></div>)}<p>{evaluation.score === 3 ? 'Вы уточнили задачу, задали вопрос и предложили действие. В рабочей версии качество формулировок дополнительно проверяет ИИ и наставник.' : 'Уточните ожидаемый результат, задайте клиенту вопрос и предложите конкретный следующий шаг.'}</p></div>}<p className="small-note">В этом макете проверяются учебные признаки ответа. Это демонстрация процесса, а не полноценная оценка ИИ.</p><div className="modal-actions"><Button variant="ghost" onClick={() => setStep(1)}>Назад</Button>{evaluation?.score === 3 && evaluation.valid ? <Button icon="check" onClick={finish}>Завершить практику</Button> : <Button icon="spark" disabled={answer.trim().length < 30} onClick={() => setEvaluation(evaluateAnswer(answer))}>Проверить ответ</Button>}</div></div>}{step === 3 && <div className="lesson-success"><div className="success-seal"><Icon name="check" size={38} /><span>✦</span></div><Badge tone="green">Практика завершена</Badge><h2 style={{whiteSpace: 'pre-line'}}>{lesson.success}</h2><p>{modal.daily ? 'Занятие на сегодня пройдено. Вернитесь завтра, чтобы закрепить навык.' : id < 3 ? `Блок «${module.title}» пройден. Следующий блок теперь доступен.` : 'Все базовые блоки пройдены. Продолжайте ежедневную практику.'}</p><div className="success-xp">✦ {awarded} XP <span>за освоенный навык*</span></div><small>*Баллы начисляются один раз за блок или первое ежедневное занятие в демо.</small><Button onClick={() => { onClose(); notify('Прогресс сохранён в этом браузере'); }}>Вернуться к маршруту <Icon name="arrow" size={17} /></Button></div>}</Modal>;
}

function Review({ client, onClose, data, update, notify, go, role }) {
  const pending=(data.pendingReviews||[]).find(r=>r.clientId===client.id);
  const [note,setNote]=useState(pending?.note || 'Сначала ответьте на конкретный вопрос клиента, затем уточните ожидаемый результат и согласуйте следующий шаг.');
  const [approved,setApproved]=useState(data.reviews.some(r=>r.clientId===client.id));
  const [submitted,setSubmitted]=useState(Boolean(pending));
  function approve() {
    if (approved || role!=='manager') return;
    const id='case-'+client.id;
    update(d=>({...d,reviews:[...d.reviews,{id,clientId:client.id,note,at:new Date().toISOString()}],pendingReviews:(d.pendingReviews||[]).filter(r=>r.clientId!==client.id),knowledge:[...d.knowledge.filter(k=>k.id!==id),{id,title:`Практика: ${client.company}`,category:'Из переписок',icon:'chat',body:`Вопрос клиента: «${client.messages.filter(m=>m.from==='client').at(-1)?.text || client.need}»\n\nУчебный вывод: ${note}`,source:`Учебная переписка · ${client.name}. Утверждено руководителем в демо.`,updated:'Сегодня',approved:true}]}));
    setApproved(true);notify('Пример утверждён и добавлен в базу знаний');
  }
  function submit() {
    update(d=>({...d,pendingReviews:[...(d.pendingReviews||[]).filter(r=>r.clientId!==client.id),{id:'pending-'+client.id,clientId:client.id,owner:1,note,at:new Date().toISOString()}]}));
    setSubmitted(true);notify('Вывод отправлен на проверку руководителю');
  }
  return <Modal title={'Разбор диалога'} eyebrow={role==='manager'?'ПРОВЕРКА РУКОВОДИТЕЛЕМ':'ПРЕДЛОЖИТЬ УЧЕБНЫЙ ВЫВОД'} onClose={onClose} wide><div className="review-client"><Avatar person={client}/><div><strong>{client.name}</strong><span>{client.company} · {client.channel}</span></div><Badge tone={approved?'green':'sand'}>{approved?'Утверждено':submitted?'Отправлено на проверку':'Черновик'}</Badge></div><div className="review-content-grid"><div><span className="eyebrow">ЦИТАТА И КОНТЕКСТ</span><blockquote className="review-quote">«{client.messages.filter(m=>m.from==='client').at(-1)?.text || client.need}»</blockquote><h4>Что оцениваем</h4><p>Ответ по существу, уточнение задачи и договорённость о следующем действии.</p><h4>На что опираемся</h4><p>Только на наблюдаемые действия и реплики. Один вопрос клиента не означает отказ от предложения.</p></div><div><AIFlag>Учебный вывод · демосценарий</AIFlag><label className="form-label">{role==='manager'?'Проверьте и отредактируйте':'Сформулируйте полезный вывод'}<textarea rows={7} value={note} disabled={approved} maxLength={2000} onChange={e=>{setNote(e.target.value);setSubmitted(false);}}/></label><p className="small-note">{role==='manager'?'После утверждения материал становится доступен всей команде.':'Вывод появится в общей базе только после проверки руководителем.'}</p></div></div><div className="modal-actions">{approved?<><Button variant="secondary" onClick={()=>{onClose();go('knowledge');}}>Открыть базу знаний</Button><Button icon="book" onClick={()=>{onClose();go('academy');}}>К обучению</Button></>:<><Button variant="ghost" onClick={onClose}>Закрыть</Button>{role==='manager'?<Button icon="check" disabled={note.trim().length<20} onClick={approve}>Утвердить для обучения</Button>:<Button icon={submitted?'check':'send'} disabled={submitted||note.trim().length<20} onClick={submit}>{submitted?'На проверке у руководителя':'Отправить на проверку'}</Button>}</>}</div></Modal>;
}

function NewClient({role,onClose,update,notify}) {
  function submit(e){
    e.preventDefault();const form=new FormData(e.currentTarget);const name=form.get('name').trim();const company=form.get('company').trim();if(!name||!company)return;
    const client={id:'custom-'+Date.now(),name,company,initials:name.split(/\s+/).slice(0,2).map(s=>s[0]).join(''),color:'sage',channel:form.get('channel'),stage:0,amount:Number(form.get('amount'))||0,unread:false,last:'Новый учебный контакт',time:'Сейчас',owner:role==='manager'?Number(form.get('owner'))||1:1,need:form.get('need').trim()||'Задача ещё не уточнена',interest:'Уточняется',messages:[]};
    update(d=>({...d,clients:[...d.clients,client]}));onClose();notify('Клиент добавлен');
  }
  return <Modal title="Новый клиент" onClose={onClose}><form onSubmit={submit}><label className="form-label">Имя и фамилия<input required name="name" maxLength={80} placeholder="Например, Иван Петров"/></label><label className="form-label">Компания<input required name="company" maxLength={100} placeholder="Название компании"/></label><div className="form-columns"><label className="form-label">Канал<select name="channel"><option>Telegram</option><option>MAX</option></select></label><label className="form-label">Сумма, ₽<input name="amount" type="number" min="0" max="100000000" defaultValue="0"/></label></div>{role==='manager'&&<label className="form-label">Ответственный<select name="owner">{team.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>}<label className="form-label">Задача клиента<textarea name="need" rows={3} maxLength={600} placeholder="Что нужно клиенту?"/></label><p className="small-note">Используйте вымышленные данные. Изменения сохраняются в этом браузере.</p><div className="modal-actions"><Button type="submit" icon="plus">Добавить клиента</Button></div></form></Modal>;
}
function NewTask({client,data,onClose,update,notify}) {
  const [mode,setMode]=useState('exact');
  const [initial]=useState(()=>dateFields(Date.now()+3600000));
  const [error,setError]=useState('');
  function submit(e){
    e.preventDefault();const f=new FormData(e.currentTarget);const title=f.get('title').trim();if(!title)return;
    let deadline;try{deadline=createDeadline(mode,f.get('date'),f.get('time'));}catch(err){setError(err.message);return;}
    const clientId=client?.id||f.get('clientId')||null;const chosen=data.clients.find(c=>c.id===clientId);
    update(d=>({...d,tasks:[...d.tasks,{id:Date.now(),title,clientId,owner:chosen?.owner||1,...deadline,done:false}]}));onClose();notify(mode==='within24h'?'Задача добавлена. На выполнение — 24 часа':'Задача добавлена');
  }
  return <Modal title="Новая задача" eyebrow={client?.company} onClose={onClose}><form onSubmit={submit}><label className="form-label">Что нужно сделать<input required name="title" maxLength={200} placeholder="Например, отправить предложение"/></label>{!client&&<label className="form-label">Клиент<select name="clientId"><option value="">Без клиента</option>{data.clients.map(c=><option key={c.id} value={c.id}>{c.company} · {c.name}</option>)}</select></label>}<fieldset className="task-deadline-choice"><legend>Когда выполнить</legend><div>{[['exact','Точная дата и время'],['within24h','В течение 24 часов']].map(([id,label])=><label key={id} className={mode===id?'selected':''}><input type="radio" name="deadlineMode" value={id} checked={mode===id} onChange={()=>{setMode(id);setError('');}}/>{label}</label>)}</div></fieldset><div className="form-columns" hidden={mode!=='exact'}><label className="form-label">Дата<input required={mode==='exact'} disabled={mode!=='exact'} type="date" name="date" defaultValue={initial.date}/></label><label className="form-label">Время<input required={mode==='exact'} disabled={mode!=='exact'} type="time" name="time" defaultValue={initial.time}/></label></div>{mode==='within24h'?<p className="task-deadline-help"><Icon name="clock" size={19}/><span>Любой момент в течение суток.<small>Отсчёт начнётся после сохранения. Точный час выбирать не нужно.</small></span></p>:<p className="small-note">Дата и время по Москве (UTC+3).</p>}{error&&<p role="alert" className="overdue">{error}</p>}<div className="modal-actions"><Button variant="ghost" type="button" onClick={onClose}>Отмена</Button><Button type="submit" icon="check">Сохранить задачу</Button></div></form></Modal>;
}
function NewKnowledge({ onClose, update, notify }) { function submit(e) { e.preventDefault(); const f = new FormData(e.currentTarget); const title = f.get('title').trim(); const body = f.get('body').trim(); if (!title || body.length < 20) return; update(d => ({ ...d, knowledge: [...d.knowledge, { id: 'note-' + Date.now(), title, body, category: f.get('category'), icon: 'file', source: 'Учебный материал · добавлен в деморежиме наставника', updated: 'Сегодня', approved: true }] })); onClose(); notify('Учебный материал добавлен'); } return <Modal title="Добавить знание команды" eyebrow="ДЕМОРЕЖИМ НАСТАВНИКА" onClose={onClose}><form onSubmit={submit}><label className="form-label">Название<input name="title" required maxLength={140} /></label><label className="form-label">Категория<select name="category">{['Методология', 'Продукт', 'Возражения', 'Коммуникация'].map(c => <option key={c}>{c}</option>)}</select></label><label className="form-label">Материал<textarea name="body" required minLength={20} maxLength={10000} rows={7} placeholder="Опишите правило и приведите пример…" /></label><p className="small-note">Добавление показывает процесс утверждения. Реальные права наставника появятся после подключения авторизации.</p><div className="modal-actions"><Button type="submit" icon="check">Утвердить и сохранить</Button></div></form></Modal>; }
function AskKnowledge({ data, onClose, setModal }) { const [query, setQuery] = useState(''); const [asked, setAsked] = useState(false); const matches = searchKnowledge(data.knowledge, query); return <Modal title="Спросить базу знаний" eyebrow="ПОИСК С УКАЗАНИЕМ ИСТОЧНИКА" onClose={onClose} wide><form className="ask-form" onSubmit={e => { e.preventDefault(); setAsked(true); }}><input aria-label="Вопрос базе знаний" value={query} required minLength={3} onChange={e => { setQuery(e.target.value); setAsked(false); }} placeholder="Например: как отвечать на возражение о цене?" /><Button type="submit" icon="search">Найти</Button></form><div className="example-queries">{['Как отвечать на дорого?', 'Следующий шаг', 'Результат кампании'].map(s => <button key={s} onClick={() => { setQuery(s); setAsked(true); }}>{s}</button>)}</div>{asked && <div className="knowledge-answer">{matches.length ? <><Badge tone="green">Найдено в утверждённых материалах</Badge>{matches.slice(0, 3).map(m => <div className="search-result" key={m.id}><h3>{m.title}</h3><p>{m.body}</p><button onClick={() => setModal({ type: 'article', article: m })}><Icon name="file" size={14} />{m.source}<Icon name="arrow" size={14} /></button></div>)}</> : <Empty title="В базе нет подходящего материала" text="Попробуйте другие слова. В демо нет генерации ответа при отсутствии источника." />}</div>}<p className="small-note">Локальный поиск по словам. После интеграции GPT сможет составлять ответ из выбранных фрагментов.</p></Modal>; }
function GlobalSearch({ initialQuery = '', role, data, onClose, openChat, setModal, go }) { const [q, setQ] = useState(initialQuery); const clients = data.clients.filter(c => (c.name + ' ' + c.company).toLowerCase().includes(q.toLowerCase())); const docs = data.knowledge.filter(k => k.title.toLowerCase().includes(q.toLowerCase())); return <Modal title="Найти в рабочем пространстве" eyebrow="КЛИЕНТЫ · ЗНАНИЯ · РАЗДЕЛЫ" onClose={onClose}><label className="input-search global-search-input"><Icon name="search" size={19} /><input autoFocus aria-label="Поиск по рабочему пространству" placeholder="Введите имя, компанию или тему" value={q} onChange={e => setQ(e.target.value)} /></label><div className="global-results">{q ? <><span className="eyebrow">КЛИЕНТЫ</span>{clients.map(c => <button key={c.id} onClick={() => { onClose(); openChat(c.id); }}><Avatar person={c} size="small" /><span>{c.name}<small>{c.company}</small></span><Icon name="arrow" size={16} /></button>)}<span className="eyebrow">БАЗА ЗНАНИЙ</span>{docs.map(k => <button key={k.id} onClick={() => setModal({ type: 'article', article: k })}><Icon name="file" size={18} /><span>{k.title}</span><Icon name="arrow" size={16} /></button>)}{!clients.length && !docs.length && <Empty />}</> : nav.filter(n => roleViews[role].includes(n.id)).map(n => <button key={n.id} onClick={() => { onClose(); go(n.id); }}><Icon name={n.icon} size={18} /><span>{role === 'employee' ? n.employeeName || n.name : n.name}</span><Icon name="arrow" size={16} /></button>)}</div></Modal>; }

class ErrorBoundary extends React.Component { constructor(props) { super(props); this.state = { error: false }; } static getDerivedStateFromError() { return { error: true }; } render() { if (this.state.error) return <div className="app-error"><h1>Давайте начнём с чистого листа</h1><p>Не удалось открыть сохранённое состояние макета. Можно скачать данные и сбросить демо.</p><button onClick={() => { const raw = localStorage.getItem(STORAGE_KEY) || '{}'; const url = URL.createObjectURL(new Blob([raw], { type: 'application/json' })); const a = document.createElement('a'); a.href = url; a.download = 'royal-reach-recovery.json'; a.click(); URL.revokeObjectURL(url); }}>Скачать сохранённые данные</button><button onClick={() => { localStorage.removeItem(STORAGE_KEY); location.hash = 'overview'; location.reload(); }}>Сбросить демо</button></div>; return this.props.children; } }
createRoot(document.getElementById('root')).render(<ErrorBoundary><App /></ErrorBoundary>);
